<p style="margin: 0 0 12px 0;">
<script>
(function () {
    var raiz = document.getElementById('folclor-clasifica');
    if (!raiz) return;

    raiz.querySelectorAll('.fc-item button').forEach(function (boton) {
        boton.addEventListener('click', function () {
            var item = boton.closest('.fc-item');
            var salida = item.querySelector('.fc-respuesta');
            var correcta = item.getAttribute('data-correcta');
            var elegida = boton.getAttribute('data-opcion');

            if (elegida === correcta) {
                salida.textContent = 'Correcto.';
            } else {
                salida.textContent = 'Intenta de nuevo.';
            }
        });
    });
})();
</script>
</p>
